window.TTSeasonContent={"halloween":[{"id":"halloween-haunted-yard","line":"All tools accounted for. The footprints on the ceiling remain unexplained.","bulletin":"The skeleton crew is literal this week. Please stop assigning them heavy lifting.","incidentTitle":"Broom Parking Dispute","incidentText":"A witch parked across the loading bay. Her claim that she was only hovering has been referred to management.","jokes":["The ghost asked for a permanent position. We said he already had excellent transparency.","The skeleton brought his own tools. Every socket was a joint venture.","Our haunted jobsite finally passed inspection. The inspector has not been seen since."],"puzzle":{"title":"The Phantom Locker","text":"Three lockers hold a broom, a lantern and a key, one each. The broom is in A. The key is not in B. Which locker holds the lantern?","answers":["B","LOCKER B"],"hint":"Place the broom first, then the key.","reveal":"B. A holds the broom, C the key, leaving B for the lantern."},"levels":[{"id":"haunted-route","title":"Escape the haunted yard","question":"The numbered paths show walking minutes. You may use any connecting path. What is the fastest route from Gate to Exit?","choices":{"A":"Gate–Crypt–Exit","B":"Gate–Shed–Exit","C":"Gate–Crypt–Shed–Exit","D":"Gate–Shed–Crypt–Exit"},"answer":"C","hint":"The shortest route can have more stops.","breakdown":"Gate → Crypt → Shed → Exit takes 2 + 1 + 2 = 5 minutes. The alternatives take 11, 8 and 16.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Haunted yard paths; numbers are minutes\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><g stroke=\"#ac84d6\" stroke-width=\"5\"><path d=\"M45 100L150 40 295 100 150 165 45 100M150 40V165\"/></g><g fill=\"#ffba65\" font-size=\"16\"><text x=\"12\" y=\"105\">Gate</text><text x=\"112\" y=\"29\">Crypt</text><text x=\"280\" y=\"105\">Exit</text><text x=\"112\" y=\"192\">Shed</text><text x=\"77\" y=\"60\">2</text><text x=\"230\" y=\"58\">9</text><text x=\"78\" y=\"151\">6</text><text x=\"230\" y=\"155\">2</text><text x=\"158\" y=\"103\">1</text></g></svg>","rank":"Apprentice"},{"id":"potion-order","title":"Keep the brew green","question":"The frog goes in after the moss. Moonwater goes in before the moss. The spark goes in immediately after the frog. Which recipe works?","choices":{"A":"Moss, water, frog, spark","B":"Water, moss, frog, spark","C":"Water, frog, moss, spark","D":"Water, moss, spark, frog"},"answer":"B","hint":"Find the only order satisfying all three rules.","breakdown":"Moonwater precedes moss; moss precedes frog; spark follows frog immediately.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">MOONWATER before MOSS</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">MOSS before FROG</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">SPARK immediately after FROG</text></svg>","rank":"Journeyman"},{"id":"witch-delivery","title":"The midnight delivery window","question":"One witch must make three separate broom trips, each starting and ending at the yard. Crypt takes 8 min round trip and closes at 18:15; Mill takes 12 min and closes at 18:25; Tower takes 10 min and closes at 18:40. Start at 18:00. Each trip must finish before its closing time. Which order works?","choices":{"A":"Mill, Crypt, Tower","B":"Tower, Mill, Crypt","C":"Crypt, Mill, Tower","D":"Crypt, Tower, Mill"},"answer":"C","hint":"Track the return time after each complete trip.","breakdown":"Crypt finishes 18:08, Mill 18:20, Tower 18:30. In D, Mill finishes 18:30, too late; A and B miss the Crypt deadline.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">CRYPT: 8 min · closes 18:15</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">MILL: 12 min · closes 18:25</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">TOWER: 10 min · closes 18:40</text></svg>","rank":"Foreman"}],"fact":"Bats are mammals, and their wings are supported by elongated finger bones.","factDetail":"","extraFacts":["A bat’s thin wing membrane stretches between its fingers.","Bats use powered flight rather than simply gliding.","Many bats use echolocation to locate objects in darkness.","Not every bat species relies on echolocation in the same way."]},{"id":"halloween-carnival","line":"The pumpkin has been promoted. It already has more openings than management.","bulletin":"Do not feed the cauldron after midnight. Purchasing has refused to issue another frog.","incidentTitle":"Unauthorized Haunting","incidentText":"A ghost repeatedly triggered the motion light. It has been assigned to night security.","jokes":["The witch requested a cordless broom. Apparently the extension lead was ruining the entrance.","The vampire joined payroll. He prefers his deductions at source.","The pumpkin applied for management. We admired its ability to look bright while being completely hollow."],"puzzle":{"title":"The Pumpkin Code","text":"The code has three digits. The first is 4. The second is twice the first. The third is the first minus 1. What is the code?","answers":["483"],"hint":"Work one digit at a time.","reveal":"483: 4, 8 and 3."},"levels":[{"id":"shadow-match","title":"Find the matching shadow","question":"A lantern casts the silhouette shown. Which object matches its outline?","choices":{"A":"Round pumpkin with straight stem","B":"Tall bottle with narrow neck","C":"Five-pointed star","D":"Witch hat with bent tip"},"answer":"D","hint":"Look at the bend at the top and the wide brim.","breakdown":"The bent peak and broad horizontal brim belong to the witch hat.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Silhouette with bent peak and wide brim\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><path d=\"M180 25l40 20-22 13 38 87 70 18H55l70-18 40-107z\" fill=\"#ad91c6\"/></svg>","rank":"Apprentice"},{"id":"carnival-token","title":"Spend the carnival tokens","question":"You have 11 tokens. Ghost train costs 4, pumpkin toss 3, maze 5. You want two DIFFERENT attractions and exactly 2 tokens left. Which pair?","choices":{"A":"Train + toss","B":"Train + maze","C":"Toss + maze","D":"Any pair"},"answer":"B","hint":"Spend exactly 9.","breakdown":"The train and maze cost 4 + 5 = 9, leaving 2.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">11 TOKENS AVAILABLE</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">Train 4 · Toss 3 · Maze 5</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">Choose two different attractions</text></svg>","rank":"Journeyman"},{"id":"lantern-switch","title":"Which switch is broken?","question":"Four lanterns start OFF. Switch X toggles lanterns 1 and 2; Y toggles 2 and 3; Z toggles 3 and 4. You press X, Y, then Z once. Which lanterns finish ON?","choices":{"A":"1 and 4","B":"2 and 3","C":"All four","D":"None"},"answer":"A","hint":"A lantern toggled twice returns to OFF.","breakdown":"Lanterns 2 and 3 toggle twice. Lanterns 1 and 4 toggle once.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">X → lanterns 1 + 2</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">Y → lanterns 2 + 3</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">Z → lanterns 3 + 4</text></svg>","rank":"Foreman"}],"fact":"A pumpkin is botanically a fruit because it develops from a flower and contains seeds.","factDetail":"","extraFacts":["Pumpkins belong to the squash family.","The hard outer rind protects the seeds and flesh.","Pumpkin flowers can be male or female on the same plant.","Different pumpkin varieties are grown for carving and cooking."]},{"id":"halloween-after-hours","line":"The ghost clocked out. His unfinished business has been reassigned.","bulletin":"The black cat is not a replacement for a superintendent. Its timesheets are, however, better.","incidentTitle":"Cauldron Overflow","incidentText":"The recipe called for one pinch. The crew used a shovel because it was already out.","jokes":["The mummy asked for a uniform allowance. He has been wearing company wraps for years.","The werewolf requested a shift change. We asked him to stop taking it so literally.","The haunted drill only works when nobody is watching. Management calls that familiar."],"puzzle":{"title":"The Night Shift","text":"A ghost works every second night, starting Monday. Which is the third night it works?","answers":["FRIDAY","FRI"],"hint":"Count working nights, including Monday.","reveal":"Friday: Monday, Wednesday, Friday."},"levels":[{"id":"ghost-grid","title":"The missing lantern","question":"On this 3 × 3 grid, the lantern is east of the frog and north of the pumpkin. Frog is B2; pumpkin is C3. Which cell holds the lantern?","choices":{"A":"A2","B":"B3","C":"C2","D":"C1"},"answer":"C","hint":"Columns run A to C left to right; rows 1 to 3 top to bottom.","breakdown":"East of B2 gives C2. C2 is also north of C3.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">Columns: A   B   C</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">Rows: 1 (top) → 3 (bottom)</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">Frog B2 · Pumpkin C3</text></svg>","rank":"Apprentice"},{"id":"bat-rotation","title":"The bat returns","question":"A bat points north. It turns 90° clockwise, 180° counterclockwise, then 90° clockwise. Which way does it point?","choices":{"A":"North","B":"East","C":"South","D":"West"},"answer":"A","hint":"Track direction after each turn.","breakdown":"North → east → west → north.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">NORTH</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">90° clockwise</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">180° counterclockwise</text><rect x=\"18\" y=\"144\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"167\" fill=\"#f7dfaa\" font-size=\"14\">90° clockwise</text></svg>","rank":"Journeyman"},{"id":"haunted-inventory","title":"Audit the haunted tool chest","question":"The chest began with 8 lanterns. Three were issued. Two of those returned. Then 4 new lanterns arrived. One lantern in the chest broke and was removed. How many usable lanterns are in the chest?","choices":{"A":"9","B":"10","C":"11","D":"12"},"answer":"B","hint":"Track only what is physically in the chest.","breakdown":"8 − 3 + 2 + 4 − 1 = 10 usable lanterns.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">Start 8 · issued 3</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">Returned 2 · new 4</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">Removed broken 1</text></svg>","rank":"Foreman"}],"fact":"Fog consists of tiny liquid water droplets suspended near the ground.","factDetail":"","extraFacts":["Fog and clouds both contain suspended droplets.","Air close to saturation can form fog as it cools.","Fog reduces visibility by scattering light.","Mist is generally less dense than fog."]}],"christmas":[{"id":"christmas-workshop","line":"All batteries charged. The elves have requested collective bargaining.","bulletin":"Wrapping a damaged tool does not change its condition. The ribbon has been noted.","incidentTitle":"Sleigh Bay Obstruction","incidentText":"A reindeer occupied the delivery bay. It refused to move without a revised feed allowance.","jokes":["Santa asked for a progress update. We showed him last year’s drawing with a new date.","The elf requested a standing desk. We handed him a toolbox.","Our Christmas bonus arrived in a festive envelope. The envelope was the bonus."],"puzzle":{"title":"The Red Parcel","text":"Three parcels are red, blue and gold. The red parcel is heavier than blue. Gold is heavier than red. Which is lightest?","answers":["BLUE"],"hint":"Put the three parcels in weight order.","reveal":"Blue, then red, then gold."},"levels":[{"id":"ribbon-cut","title":"Ribbon without a splice","question":"A 2 m ribbon must wrap a parcel using 145 cm, then leave 20 cm for the bow. How much remains?","choices":{"A":"15 cm","B":"25 cm","C":"35 cm","D":"55 cm"},"answer":"C","hint":"Convert metres to centimetres.","breakdown":"200 − 145 − 20 = 35 cm.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">RIBBON 2 m</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">WRAP 145 cm</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">BOW 20 cm</text></svg>","rank":"Apprentice"},{"id":"sleigh-stops","title":"Find the delivery address","question":"The delivery is on the north side of Pine Street, between houses 12 and 16, and has an even number. Which address?","choices":{"A":"13","B":"14","C":"15","D":"18"},"answer":"B","hint":"Only one even number lies strictly between 12 and 16.","breakdown":"14 is even and between 12 and 16.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">PINE STREET · NORTH SIDE</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">12     ?     16</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">EVEN HOUSE NUMBER</text></svg>","rank":"Journeyman"},{"id":"elf-dependency","title":"Workshop handoff","question":"The box must be assembled before painting. Paint takes 20 minutes to dry after painting ends. Wrapping takes 5 minutes and must wait for dry paint. Assembly takes 10 minutes; painting takes 5. Start 09:00 with one parcel. Earliest finish?","choices":{"A":"09:20","B":"09:30","C":"09:35","D":"09:40"},"answer":"D","hint":"The drying period starts at the end of painting.","breakdown":"Assembly ends 09:10; painting 09:15; dry 09:35; wrapped 09:40.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">ASSEMBLE 10 min → PAINT 5 min</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">DRY 20 min after painting</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">WRAP 5 min after drying</text></svg>","rank":"Foreman"}],"fact":"Evergreen trees retain foliage through the winter rather than shedding all their leaves at once.","factDetail":"","extraFacts":["Many conifers have needle-shaped leaves.","Needles are replaced over time rather than all at once each autumn.","Cones are reproductive structures of conifers.","Not all conifers are evergreen; larches shed their needles."]},{"id":"christmas-deliveries","line":"The sleigh is loaded. Nobody has signed the tool transfer.","bulletin":"Reindeer tracks do not count as a delivery receipt.","incidentTitle":"Unauthorized Gift Substitution","incidentText":"A missing laser was replaced with a chocolate orange. Its accuracy remains under review.","jokes":["The snowman joined the crew. First warm day and he completely fell apart.","The elves labelled every drawer. We have never felt so threatened.","The reindeer submitted mileage. Apparently flying still counts as travel time."],"puzzle":{"title":"The Missing Stocking","text":"Four stockings hang left to right. Holly is first. Noel is immediately right of Holly. Star is last. What position holds the remaining stocking?","answers":["3","THIRD","THREE"],"hint":"Fill the stated positions.","reveal":"Third. First, second and fourth are already occupied."},"levels":[{"id":"gift-balance","title":"Balance the gift scale","question":"Two identical red gifts balance one blue gift weighing 6 kg. One red and one green gift together weigh 8 kg. How much does green weigh?","choices":{"A":"2 kg","B":"3 kg","C":"5 kg","D":"6 kg"},"answer":"C","hint":"Find the red weight first.","breakdown":"Each red weighs 3 kg; green weighs 8 − 3 = 5 kg.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">RED + RED = BLUE (6 kg)</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">RED + GREEN = 8 kg</text></svg>","rank":"Apprentice"},{"id":"snowflake-symmetry","title":"Fold the snowflake","question":"A paper square is folded exactly in half once. One circular hole is punched through both layers, away from the fold and all edges. How many holes appear after unfolding?","choices":{"A":"1","B":"2","C":"3","D":"4"},"answer":"B","hint":"The punch passes through two separate layers.","breakdown":"Unfolding reveals two mirrored holes.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Folded square with one punched hole\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><path d=\"M65 35h230v130H65z\" fill=\"none\" stroke=\"#d4d5ff\" stroke-width=\"3\"/><path d=\"M180 35v130\" stroke=\"#d4d5ff\" stroke-dasharray=\"6\"/><circle cx=\"240\" cy=\"90\" r=\"13\" fill=\"#c888ff\"/><text x=\"130\" y=\"190\" fill=\"#f7dfaa\" font-size=\"14\">ONE FOLD</text></svg>","rank":"Journeyman"},{"id":"sleigh-capacity","title":"Two-trip loading plan","question":"A sleigh carries at most 10 kg each trip. Parcels weigh 6, 5, 4 and 3 kg. Which grouping delivers all four in exactly two trips without overloading?","choices":{"A":"6+5 / 4+3","B":"6+4 / 5+3","C":"6+3+4 / 5","D":"6+5+4 / 3"},"answer":"B","hint":"Both trip totals must be at most 10.","breakdown":"6 + 4 = 10 and 5 + 3 = 8.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">LIMIT: 10 kg PER TRIP</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">PARCELS: 6, 5, 4, 3 kg</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">TWO TRIPS</text></svg>","rank":"Foreman"}],"fact":"Snowflakes grow as water vapour freezes onto ice crystals.","factDetail":"","extraFacts":["The common sixfold structure reflects the arrangement of water molecules in ice.","Temperature affects crystal shape as it grows.","Humidity also affects snow-crystal growth.","Snow can contain irregular crystals and clumps as well as classic flakes."]},{"id":"christmas-lights","line":"Festive lights installed. The extension cord has become the site’s longest employee.","bulletin":"The workshop wishes to remind staff that tinsel is neither insulation nor a repair method.","incidentTitle":"Tree Relocation Review","incidentText":"The tree was moved three times before anyone checked the ceiling height.","jokes":["The foreman put a star on the schedule. It is still a work of fiction.","We asked the tree to improve its attitude. It said it was already fully lit.","The elf said the job was a wrap. We found three outstanding deficiencies under the bow."],"puzzle":{"title":"The Bell Sequence","text":"Bells ring in this order: low, high, high, low, high, high, low. Which pitch is next?","answers":["HIGH"],"hint":"Look for a repeating group of three.","reveal":"High. The repeating group is low, high, high."},"levels":[{"id":"ornament-mirror","title":"Read the ornament row","question":"The row is STAR, BELL, TREE, MOON from left to right. Viewed in a mirror directly in front of it, which symbol appears second from the left?","choices":{"A":"Star","B":"Bell","C":"Tree","D":"Moon"},"answer":"C","hint":"Reverse the row.","breakdown":"The mirrored row is MOON, TREE, BELL, STAR.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">STAR   BELL   TREE   MOON</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">MIRROR reverses left and right</text></svg>","rank":"Apprentice"},{"id":"light-fault","title":"Find the disconnected link","question":"In this fictional light circuit, power travels A → B → C → D. A and B glow; C and D do not. Every bulb is good and exactly one link is disconnected. Which link?","choices":{"A":"Supply–A","B":"A–B","C":"B–C","D":"C–D"},"answer":"C","hint":"Power reaches B but not C.","breakdown":"Only a break between B and C matches both working and dark lights.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">SUPPLY → A → B → C → D</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">A ON · B ON · C OFF · D OFF</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">Logic model only; not wiring advice</text></svg>","rank":"Journeyman"},{"id":"holiday-roster","title":"Cover the workshop","question":"Two elves are needed at every hour from 09:00 to 12:00. Ada works 09–11; Bo works 10–12; Cam works 09–10 and 11–12. Is any extra coverage required?","choices":{"A":"None","B":"09–10 only","C":"10–11 only","D":"11–12 only"},"answer":"A","hint":"Check the three one-hour blocks.","breakdown":"09–10 Ada/Cam; 10–11 Ada/Bo; 11–12 Bo/Cam. Each block has two.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">ADA 09–11</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">BO 10–12</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">CAM 09–10 + 11–12</text></svg>","rank":"Foreman"}],"fact":"An LED produces light using a semiconductor.","factDetail":"","extraFacts":["LED stands for light-emitting diode.","LEDs can produce different colours depending on their materials.","A light string includes more than just its visible LEDs.","A failed light string should be handled according to its manufacturer’s instructions."]},{"id":"christmas-finale","line":"The gifts are delivered. The empty boxes have somehow become our problem.","bulletin":"The North Pole has requested closeout photos. “It looked good in the dark” was declined.","incidentTitle":"Cookie Evidence Missing","incidentText":"All inspection cookies disappeared. The cat has retained counsel.","jokes":["Santa left us a punch list. Apparently naughty and nice were just preliminary categories.","The crew asked for a white Christmas. Accounting sent another blank expense form.","The gingerbread house failed its inspection. Nobody could produce the engineer’s icing schedule."],"puzzle":{"title":"The Last Gift","text":"A gift is not in the sleigh or workshop. It must be in exactly one of the sleigh, workshop or cabin. Where is it?","answers":["CABIN","THE CABIN"],"hint":"Eliminate the two impossible locations.","reveal":"The cabin."},"levels":[{"id":"cookie-path","title":"Cookie trail","question":"Follow these instructions from START: go to the BELL, then take its arrow to the STAR, then follow the STAR’s arrow. Where do you finish?","choices":{"A":"Tree","B":"Gift","C":"Moon","D":"Bell"},"answer":"B","hint":"Use the arrows, not the visual order.","breakdown":"BELL points to STAR, and STAR points to GIFT.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">START → BELL</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">BELL → STAR</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">STAR → GIFT</text><rect x=\"18\" y=\"144\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"167\" fill=\"#f7dfaa\" font-size=\"14\">MOON → TREE</text></svg>","rank":"Apprentice"},{"id":"gift-overlap","title":"Avoid counting twice","question":"Of 12 parcels, 7 have red ribbon and 6 have green tags. Exactly 3 have both. How many have neither?","choices":{"A":"0","B":"1","C":"2","D":"3"},"answer":"C","hint":"Subtract the overlap once when counting the union.","breakdown":"7 + 6 − 3 = 10 have at least one feature; 12 − 10 = 2 have neither.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">12 PARCELS TOTAL</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">RED RIBBON 7 · GREEN TAG 6</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">BOTH 3</text></svg>","rank":"Journeyman"},{"id":"santa-comparison","title":"Choose the courier","question":"Courier A charges $15 plus $2 per parcel. Courier B charges $5 per parcel. For 8 parcels, which is cheaper and by how much?","choices":{"A":"A by $9","B":"B by $9","C":"A by $15","D":"Same price"},"answer":"A","hint":"Calculate both complete prices.","breakdown":"A = 15 + 2×8 = $31. B = 5×8 = $40. A saves $9.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">A: $15 + $2 per parcel</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">B: $5 per parcel</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">8 parcels</text></svg>","rank":"Foreman"}],"fact":"Glass ornaments are often made by shaping heated glass before it cools.","factDetail":"","extraFacts":["Glass can be shaped while hot and soft.","A hollow ornament uses less glass than a solid one of the same size.","Thin glass walls are vulnerable to impact.","Protective packaging keeps ornaments from striking each other."]},{"id":"newyear-reset","line":"New year. Same mysterious charger that belongs to nobody.","bulletin":"Resolutions must include a location, owner and expected completion date.","incidentTitle":"Countdown Dispute","incidentText":"The crew counted down from ten. Purchasing counted the remaining receipts.","jokes":["My resolution is to stop losing pencils. I wrote it down somewhere.","Management promised a fresh start. The coffee is still from December.","We rang in the new year. Nobody recorded who borrowed the bell."],"puzzle":{"title":"The Midnight Clock","text":"It is 23:40. In 35 minutes, what time will it be? Use 24-hour time.","answers":["00 15","0015","0 15"],"hint":"Cross midnight after the first 20 minutes.","reveal":"00:15."},"levels":[{"id":"countdown-intersection","title":"Two countdown bells","question":"Bell A rings every 4 minutes; bell B every 6 minutes. Both ring at midnight. When do they next ring together?","choices":{"A":"00:08","B":"00:10","C":"00:12","D":"00:24"},"answer":"C","hint":"Find the smallest positive common multiple.","breakdown":"The least common multiple of 4 and 6 is 12.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">BELL A every 4 min</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">BELL B every 6 min</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">BOTH at 00:00</text></svg>","rank":"Apprentice"},{"id":"firework-probability","title":"Pick the finale ticket","question":"A bag contains 3 gold and 2 silver tickets. One is drawn without looking. What is the chance of gold?","choices":{"A":"2/5","B":"1/2","C":"3/5","D":"3/2"},"answer":"C","hint":"Favourable tickets divided by all tickets.","breakdown":"3 gold out of 5 tickets gives 3/5.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">GOLD: 3</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">SILVER: 2</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">DRAW ONE</text></svg>","rank":"Journeyman"},{"id":"annual-reset","title":"Does the average improve?","question":"The first three fictional workshop scores are 6, 8 and 10. What fourth score makes the four-score average exactly 9?","choices":{"A":"9","B":"10","C":"11","D":"12"},"answer":"D","hint":"Four scores must total 4 × 9.","breakdown":"The total must be 36. Existing scores total 24, so the fourth must be 12.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">SCORES: 6, 8, 10, ?</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">TARGET AVERAGE: 9</text></svg>","rank":"Foreman"}],"fact":"A leap year adds a day to February to help keep the calendar aligned with the solar year.","factDetail":"","extraFacts":["Most years divisible by four are leap years.","Century years are exceptions unless divisible by 400.","February has 29 days in a leap year.","The Gregorian calendar uses this rule to limit accumulated drift."]},{"id":"winter-closeout","line":"Holiday decorations packed. The extension cords have entered hibernation.","bulletin":"Please return borrowed holiday equipment before the snowman’s exit interview.","incidentTitle":"Ornament Inventory","incidentText":"One box marked lights contained cables, one glove and a very confident label.","jokes":["The snow shovel wants a raise. It says it has been carrying the whole driveway.","We packed away the tree. The glitter has declined to leave.","January arrived with a clean slate. Someone immediately used it as a cutting board."],"puzzle":{"title":"The Winter Row","text":"Five boots are numbered 1 to 5. You remove all odd-numbered boots. Which numbers remain?","answers":["2 4","2 AND 4"],"hint":"Keep only the even numbers.","reveal":"2 and 4."},"levels":[{"id":"snow-track","title":"Who left the tracks?","question":"The trail repeats boot, boot, paw. The first print is a boot. What is print 9?","choices":{"A":"Boot","B":"Paw","C":"Hoof","D":"Cannot tell"},"answer":"B","hint":"Mark the end of each group of three.","breakdown":"Prints 3, 6 and 9 are paws.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">BOOT · BOOT · PAW</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">Repeats in groups of 3</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">PRINT 9 = ?</text></svg>","rank":"Apprentice"},{"id":"storage-stack","title":"Unpack in the right order","question":"Box A sits on B; B sits on C. Only a box with nothing on top can be removed. Which removal order works?","choices":{"A":"C, B, A","B":"B, A, C","C":"A, B, C","D":"A, C, B"},"answer":"C","hint":"Start at the top of the stack.","breakdown":"A must be removed before B; B before C.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">TOP: A</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">MIDDLE: B</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">BOTTOM: C</text></svg>","rank":"Journeyman"},{"id":"winter-stock","title":"Reserve the consumables","question":"There are 18 bags in stock. Each scheduled visit needs 4 bags. Keep a reserve of 3 bags untouched. How many complete visits can be supplied?","choices":{"A":"3","B":"4","C":"5","D":"6"},"answer":"A","hint":"Only 15 bags are available for use.","breakdown":"(18 − 3) ÷ 4 = 3 complete visits, with 3 additional usable bags left.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">STOCK 18 BAGS</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">RESERVE 3</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">4 BAGS PER VISIT</text></svg>","rank":"Foreman"}],"fact":"Fresh snow often muffles sound because its porous structure absorbs some sound energy.","factDetail":"","extraFacts":["Snow contains spaces between ice grains.","Compaction changes the structure of a snow layer.","Snow properties change with temperature and time.","A crust can behave differently from loose fresh snow."]}],"regular":[{"id":"regular-1","line":"The toolbox has a better filing system than the office.","bulletin":"All tool movements require a location. “Over there” remains outside our mapping service.","incidentTitle":"Field Review 1","incidentText":"The laser was found inside the case marked LASER. Search training will resume Monday.","jokes":["The apprentice asked where the level was. We told him to raise his standards.","The toolbox has wheels. It is now our most mobile employee.","We held a productivity meeting. Productivity was unable to attend."],"puzzle":{"title":"The Lift Order","text":"A arrives before B. C arrives after B. Which arrives second?","answers":["B"],"hint":"Write the three arrivals in order.","reveal":"B. The order is A, B, C."},"levels":[{"id":"cut-plan","title":"Save the offcut","question":"A 120 in. board must yield 48, 36 and 24 in. pieces. Each of three cuts consumes 1/8 in. of kerf. How much remains?","choices":{"A":"11 5/8 in.","B":"12 in.","C":"11 7/8 in.","D":"10 5/8 in."},"answer":"A","hint":"Subtract all three kerfs as well as finished pieces.","breakdown":"120 − 48 − 36 − 24 − 3/8 = 11 5/8 in.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">BOARD 120 in.</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">PIECES 48 + 36 + 24 in.</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">3 CUTS · 1/8 in. KERF EACH</text></svg>","rank":"Apprentice"},{"id":"drawing-scale","title":"Read the scale","question":"A drawing uses 1/4 in. = 1 ft. A drawn line measures 2 1/2 in. What actual length does it represent?","choices":{"A":"5 ft","B":"8 ft","C":"10 ft","D":"12 ft"},"answer":"C","hint":"How many quarter-inches fit in 2 1/2 inches?","breakdown":"2.5 ÷ 0.25 = 10 ft.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">SCALE: 1/4 in. = 1 ft</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">DRAWN LINE: 2 1/2 in.</text></svg>","rank":"Journeyman"},{"id":"critical-path","title":"When can the handoff happen?","question":"Task A takes 2 hours. B (3 hours) and C (5 hours) both start after A and can run in parallel. D takes 1 hour after BOTH finish. Total elapsed time?","choices":{"A":"6 hours","B":"8 hours","C":"10 hours","D":"11 hours"},"answer":"B","hint":"The slower parallel task determines the wait.","breakdown":"2 + max(3,5) + 1 = 8 hours.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">A: 2 h</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">Then B: 3 h AND C: 5 h</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">Then D: 1 h</text></svg>","rank":"Foreman"}],"fact":"A tape hook moves to compensate for its thickness.","factDetail":"","extraFacts":["The hook has a small amount of intentional play.","Inside and outside measurements load the hook in opposite directions.","A bent hook can introduce measurement error.","Check a tape against a known reference when accuracy matters."]},{"id":"regular-2","line":"Tools returned. Explanations remain outstanding.","bulletin":"All tool movements require a location. “Over there” remains outside our mapping service.","incidentTitle":"Field Review 2","incidentText":"A tape was reported inaccurate before someone checked which side of the pencil line they were using.","jokes":["The crew asked for clearer direction. Management pointed harder.","The pencil went missing. The ear has declined to comment.","The new tape measure has excellent reach and terrible boundaries."],"puzzle":{"title":"The Spare Key","text":"A key is in Shop or Truck. It is not in Truck. Where is it?","answers":["SHOP","THE SHOP"],"hint":"Eliminate the impossible place.","reveal":"Shop. Truck was ruled out."},"levels":[{"id":"tool-location","title":"Track the laser","question":"The laser starts at Shop. Ada takes it to Job A. Bo takes it from Job A to Truck. Cam returns it from Truck to Shop. Ada then takes it to Job B. Current location?","choices":{"A":"Shop","B":"Job A","C":"Truck","D":"Job B"},"answer":"D","hint":"Follow the movements chronologically.","breakdown":"The last recorded move ends at Job B.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">Shop → Job A</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">Job A → Truck</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">Truck → Shop → Job B</text></svg>","rank":"Apprentice"},{"id":"diagonal-check","title":"Which rectangle is square?","question":"For this ideal geometry puzzle, a rectangle’s sides must be 6 ft and 8 ft, and its diagonal must match Pythagoras. What diagonal should you check?","choices":{"A":"9 ft","B":"10 ft","C":"12 ft","D":"14 ft"},"answer":"B","hint":"Square the sides, add, and take the square root.","breakdown":"6² + 8² = 100; √100 = 10 ft.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"50\" y=\"35\" width=\"250\" height=\"130\" fill=\"none\" stroke=\"#cea2f2\" stroke-width=\"3\"/><path d=\"M50 35L300 165\" stroke=\"#ffba65\" stroke-dasharray=\"7\"/><g fill=\"#f7dfaa\" font-size=\"16\"><text x=\"160\" y=\"25\">8 ft</text><text x=\"7\" y=\"105\">6 ft</text><text x=\"170\" y=\"95\">?</text></g></svg>","rank":"Journeyman"},{"id":"deficiency-priority","title":"Resolve the handoff blocker","question":"Inspection is booked for 14:00. One item must be completed before inspection: access panel installation (45 min). Labels (20 min) and cleanup (30 min) can happen after. It is 13:00 with one worker. What should start first?","choices":{"A":"Cleanup","B":"Labels","C":"Access panel","D":"Wait for inspector"},"answer":"C","hint":"Protect the task with the fixed deadline.","breakdown":"The access panel must start by 13:15. Starting either other task first would miss that latest start.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">NOW 13:00 · INSPECTION 14:00</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">Panel 45 min · MUST be ready</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">Labels 20 / cleanup 30 can wait</text></svg>","rank":"Foreman"}],"fact":"A sharp saw blade generally needs less push force than a dull one.","factDetail":"","extraFacts":["Tooth count influences how a blade clears material.","Blade suitability depends on the material being cut.","Inspect blades according to the manufacturer’s instructions.","A clean cut also depends on support and feed technique."]},{"id":"regular-3","line":"The drawing is to scale. The optimism is not.","bulletin":"All tool movements require a location. “Over there” remains outside our mapping service.","incidentTitle":"Field Review 3","incidentText":"The tool chest was locked with the key still inside. Management has requested a diagram.","jokes":["Our laser has self-levelled. We are waiting for management to try it.","The drawing says typical. The site has chosen exceptional.","The toolbox is organized by urgency: everything is on top."],"puzzle":{"title":"The Toolbox Row","text":"The red box is left of blue; green is right of blue. Which colour is in the middle?","answers":["BLUE"],"hint":"Place the blue box first.","reveal":"Blue, between red and green."},"levels":[{"id":"parts-sort","title":"Spot the odd fastener","question":"The required part is M8 × 30 mm. Which bin matches both thread size and length?","choices":{"A":"M8 × 25","B":"M6 × 30","C":"M8 × 30","D":"M10 × 30"},"answer":"C","hint":"Both dimensions must match.","breakdown":"Only M8 × 30 matches the stated requirement.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">REQUIRED: M8 × 30 mm</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">Check size AND length</text></svg>","rank":"Apprentice"},{"id":"fraction-fit","title":"Check the clearance","question":"An opening is 32 3/8 in. wide and an insert is 32 1/8 in. wide. Centred evenly, what is the gap on EACH side?","choices":{"A":"1/16 in.","B":"1/8 in.","C":"1/4 in.","D":"1/2 in."},"answer":"B","hint":"Subtract widths, then split the difference.","breakdown":"The total clearance is 1/4 in.; half is 1/8 in.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">OPENING 32 3/8 in.</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">INSERT 32 1/8 in.</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">Equal gaps on both sides</text></svg>","rank":"Journeyman"},{"id":"quote-discount","title":"The real unit cost","question":"Box A: 100 anchors for $48. Box B: 50 anchors for $26 with a 10% discount. Ignoring taxes, which has lower cost per anchor?","choices":{"A":"A: 48¢","B":"B: 46.8¢","C":"Equal","D":"Cannot determine"},"answer":"B","hint":"Apply the discount before dividing by quantity.","breakdown":"B costs $23.40 for 50 = 46.8¢ each; A costs 48¢.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">A: 100 / $48</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">B: 50 / $26 less 10%</text></svg>","rank":"Foreman"}],"fact":"A right triangle follows a² + b² = c².","factDetail":"","extraFacts":["The hypotenuse is opposite the right angle.","The hypotenuse is the longest side of a right triangle.","A 3–4–5 triangle is a right triangle.","Scaling all sides keeps the same angles."]},{"id":"regular-4","line":"Progress continues despite several eyewitness accounts.","bulletin":"All tool movements require a location. “Over there” remains outside our mapping service.","incidentTitle":"Field Review 4","incidentText":"A charger was moved closer to the battery. Neither was plugged in.","jokes":["The client wanted an open concept. Purchasing opened the budget.","The offcuts have formed a committee to oppose disposal.","We bought a label maker. It has been labelled missing."],"puzzle":{"title":"The Delivery Day","text":"A delivery is two days after Tuesday. What day is it?","answers":["THURSDAY","THU"],"hint":"Count Wednesday, then the next day.","reveal":"Thursday."},"levels":[{"id":"rotation-plan","title":"Rotate the room plan","question":"A door is on the north wall of a plan. Rotate the whole plan 90° clockwise on the page. Which page edge now contains the door?","choices":{"A":"Top","B":"Right","C":"Bottom","D":"Left"},"answer":"B","hint":"North begins at the top.","breakdown":"Top rotates to right.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"85\" y=\"35\" width=\"190\" height=\"130\" fill=\"none\" stroke=\"#cea2f2\" stroke-width=\"3\"/><path d=\"M150 35h60\" stroke=\"#ffba65\" stroke-width=\"10\"/><text x=\"140\" y=\"25\" fill=\"#f7dfaa\">DOOR / NORTH</text></svg>","rank":"Apprentice"},{"id":"batch-mix","title":"Mix the test batch","question":"A fictional craft mixture uses 3 parts powder to 2 parts water by volume. For 10 cups total, how many cups are water?","choices":{"A":"2","B":"3","C":"4","D":"6"},"answer":"C","hint":"Water is 2 of 5 equal parts.","breakdown":"10 × 2/5 = 4 cups. This is a puzzle recipe, not a product mixing instruction.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">POWDER : WATER = 3 : 2</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">TOTAL = 10 CUPS</text></svg>","rank":"Journeyman"},{"id":"truck-weight","title":"Choose the load","question":"A cart has a 150 kg limit. It already holds 40 kg. Which additional load can be added without exceeding the limit?","choices":{"A":"Two 60 kg crates","B":"Three 40 kg crates","C":"Five 25 kg crates","D":"Two 50 kg crates"},"answer":"D","hint":"Only 110 kg of capacity remains.","breakdown":"Two 50 kg crates add 100, for a total of 140 kg. The other choices exceed 150.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">CART LIMIT 150 kg</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">ALREADY LOADED 40 kg</text></svg>","rank":"Foreman"}],"fact":"A board’s nominal size can differ from its finished size.","factDetail":"","extraFacts":["Surfacing removes material from rough lumber.","Actual dimensions depend on the product and standard.","Order by the supplier’s stated dimensions.","Measure existing material before planning a precise fit."]},{"id":"regular-5","line":"The missing item was found where nobody looked: its assigned location.","bulletin":"All tool movements require a location. “Over there” remains outside our mapping service.","incidentTitle":"Field Review 5","incidentText":"The missing broom was found behind the pile it was meant to remove.","jokes":["The schedule has float. Unfortunately it has drifted out to sea.","The broom received a promotion after sweeping changes.","The crew completed the punch list. A second punch list has entered the chat."],"puzzle":{"title":"The Last Drawer","text":"Four drawers are numbered 1–4. The key is in an even drawer greater than 2. Which?","answers":["4","FOUR"],"hint":"List the even drawer numbers.","reveal":"Drawer 4."},"levels":[{"id":"label-audit","title":"Find the duplicate ID","question":"Which pair must be reviewed for a duplicate COMPANY label? Personal labels are a separate pool.","choices":{"A":"B-12 and P-B-12","B":"DW-03 and B-03","C":"B-12 and B-12","D":"P-DW-03 and DW-03"},"answer":"C","hint":"Compare complete labels within the same pool.","breakdown":"Two company records labelled B-12 conflict; the other pairs have distinct complete labels.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">COMPANY: B-12 / DW-03 / B-12</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">PERSONAL: P-B-12 / P-DW-03</text></svg>","rank":"Apprentice"},{"id":"area-l-shape","title":"Read the missing corner","question":"A 10 × 8 ft rectangle has a 4 × 3 ft corner removed. What is the remaining floor area?","choices":{"A":"56 sq ft","B":"68 sq ft","C":"74 sq ft","D":"92 sq ft"},"answer":"B","hint":"Subtract the removed area from the full rectangle.","breakdown":"10×8 − 4×3 = 80 − 12 = 68 sq ft.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><path d=\"M60 35h240v70h-96v60H60z\" fill=\"#493356\" stroke=\"#cea2f2\" stroke-width=\"3\"/><g fill=\"#f7dfaa\" font-size=\"15\"><text x=\"155\" y=\"25\">10 ft</text><text x=\"15\" y=\"100\">8 ft</text><text x=\"210\" y=\"150\">4 × 3 removed</text></g></svg>","rank":"Journeyman"},{"id":"handoff-logic","title":"One key, three people","question":"Ada, Bo and Cam each did one task: open, inspect or lock. Ada did not open. Cam locked. Who opened?","choices":{"A":"Ada","B":"Bo","C":"Cam","D":"Cannot determine"},"answer":"B","hint":"Cam is already assigned; Ada cannot open.","breakdown":"Only Bo can open, so Ada inspected.","graphic":"<svg class=\"challenge-diagram\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Challenge diagram\"><rect width=\"360\" height=\"200\" rx=\"16\" fill=\"#141324\"/><rect x=\"18\" y=\"15\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"38\" fill=\"#f7dfaa\" font-size=\"14\">TASKS: OPEN / INSPECT / LOCK</text><rect x=\"18\" y=\"58\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"81\" fill=\"#f7dfaa\" font-size=\"14\">ADA did not OPEN</text><rect x=\"18\" y=\"101\" width=\"324\" height=\"35\" rx=\"7\" fill=\"#29233b\"/><text x=\"30\" y=\"124\" fill=\"#f7dfaa\" font-size=\"14\">CAM did LOCK</text></svg>","rank":"Foreman"}],"fact":"A tool’s label identifies the asset; its serial number identifies the manufacturer’s unit.","factDetail":"","extraFacts":["Two tools of the same model can have different serial numbers.","An internal label can be replaced without changing the physical serial.","Personal and company pools can use distinct label prefixes.","A good asset record preserves earlier labels in its history."]}]};
window.ttContentSelection=function(now=new Date()){
 const d=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Vancouver',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now),v=Object.fromEntries(d.map(x=>[x.type,x.value]));
 const y=+v.year,m=+v.month,day=+v.day,md=m*100+day,utc=Date.UTC(y,m-1,day),dow=new Date(utc).getUTCDay(),week=utc-((dow+6)%7)*86400000-((dow===1&&(+v.hour<4||(+v.hour===4&&+v.minute<30)))?604800000:0);
 let theme=md>=1001&&md<=1101?'halloween':md>=1201||md<=106?'christmas':'regular';
 let anchor=theme==='halloween'?Date.UTC(y,9,26):theme==='christmas'?Date.UTC(m===1?y-1:y,11,1):Date.UTC(2026,10,2);
 anchor-=((new Date(anchor).getUTCDay()+6)%7)*86400000;
 const rows=window.TTSeasonContent[theme],n=Math.floor((week-anchor)/604800000),i=((n%rows.length)+rows.length)%rows.length;
 return {theme,index:i,pack:rows[i],key:theme+'-'+rows[i].id+'-'+week};
};
